nextflow_process {

    name "Test Process CSVTK_JOIN"
    script "../main.nf"
    process "CSVTK_JOIN"

    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "csvtk"
    tag "csvtk/join"

    test("join - csv") {

        when {
            params {
                module_args = "--fields 'ID;ID' -p -e -d \"\t\" -D \",\""
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [
                        file("https://github.com/nf-core/test-datasets/raw/bacass/bacass_hybrid.csv", checkIfExists: true),
                        file("https://github.com/nf-core/test-datasets/raw/bacass/bacass_short.csv", checkIfExists: true),
                    ]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("join - csv - tsv output") {

        when {
            params {
                module_args = "--fields 'ID;ID' -p -e -d \"\t\" -T"
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
